module axis_packer #(
    parameter DWIDTH = 64,
    parameter W_KEEP = DWIDTH/8,
    parameter W_USER = 1
)
(
  input   logic                               clk,
  input   logic                               rst,

  input   logic                               i_axis_tvalid,
  input   logic   [DWIDTH-1:0]                i_axis_tdata,
  input   logic                               i_axis_tlast,
  input   logic   [W_USER-1:0]                i_axis_tuser,
  input   logic   [W_KEEP-1:0]                i_axis_tkeep,
  output  logic                               o_axis_tready,

  output  logic                               o_axis_tvalid,
  output  logic   [DWIDTH-1:0]                o_axis_tdata,
  output  logic                               o_axis_tlast,
  output  logic   [W_USER-1:0]                o_axis_tuser,
  output  logic   [W_KEEP-1:0]                o_axis_tkeep,
  input   logic                               i_axis_tready
);

logic   [(DWIDTH*2)-1:0] tdata;
logic   [DWIDTH-1    :0] wdata;
logic   [(W_KEEP*2)-1:0] tkeep;
logic   [           1:0] tlast;

logic   [DWIDTH-1    :0] tdata_r;
logic   [W_KEEP-1    :0] tkeep_r;
logic                    tlast_r;
logic                    tlast_prev;

logic [($clog2(W_KEEP))-1:0] idx;

always_comb begin
  tdata = tdata_r;
  tkeep = tkeep_r;
  tlast = tlast_r;
  if (i_axis_tvalid && o_axis_tready) begin
    tdata = (tdata_r | (wdata << (idx*8)));
    tkeep = (tkeep_r | (i_axis_tkeep << (idx)));
    tlast[0] = (i_axis_tlast && tkeep[W_KEEP+:W_KEEP] == '0);
    tlast[1] = (i_axis_tlast && tkeep[W_KEEP+:W_KEEP] != '0);
  end
end

integer i;
always_comb begin
  idx = '0;
  for (i=0;i<W_KEEP;i=i+1) begin
    idx = idx + tkeep_r[i];
  end
end

genvar j;
generate
  for (j=0;j<W_KEEP;j=j+1) begin
    assign wdata[j*8+:8] = (i_axis_tkeep[j]) ? i_axis_tdata[j*8+:8] : '0;
  end
endgenerate


always_ff @(posedge clk) begin
  if (rst) begin
    tdata_r     <= '0;
    tkeep_r     <= '0;
    tlast_r     <= '0;
    tlast_prev  <= '0;
  end
  else begin
    tdata_r    <= (o_axis_tvalid) ? tdata[DWIDTH+:DWIDTH] : tdata[0+:DWIDTH];
    tkeep_r    <= (o_axis_tvalid) ? tkeep[W_KEEP+:W_KEEP] : tkeep[0+:W_KEEP];
    tlast_r    <= (o_axis_tvalid) ? tlast[1]              : tlast[0];
    tlast_prev <= tlast[1];
  end
end

assign o_axis_tvalid = (o_axis_tkeep == '1) || (o_axis_tlast);
assign o_axis_tdata  = tdata[0+:DWIDTH];
assign o_axis_tlast  = tlast[0];
assign o_axis_tuser  = i_axis_tuser;
assign o_axis_tkeep  = tkeep[0+:W_KEEP];
assign o_axis_tready = i_axis_tready && (!tlast_prev);

endmodule// SPDX-FileCopyrightText: Copyright (c) 2023-2024 NVIDIA CORPORATION & AFFILIATES. All rights reserved.
// SPDX-License-Identifier: Apache-2.0
//
// Licensed under the Apache License, Version 2.0 (the "License");
// you may not use this file except in compliance with the License.
// You may obtain a copy of the License at
//
// http://www.apache.org/licenses/LICENSE-2.0
//
// Unless required by applicable law or agreed to in writing, software
// distributed under the License is distributed on an "AS IS" BASIS,
// WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
// See the License for the specific language governing permissions and
// limitations under the License.

module axis_reg #(
    parameter DWIDTH = 64,
    parameter SKID   = 1
)
(
    input                                       clk,
    input                                       rst,

    input                                       i_axis_rx_tvalid,
    input           [DWIDTH-1:0]                i_axis_rx_tdata,
    output                                      o_axis_rx_tready,

    output                                      o_axis_tx_tvalid,
    output          [DWIDTH-1:0]                o_axis_tx_tdata,
    input                                       i_axis_tx_tready
);

logic                 r_axis_tvalid;
logic   [DWIDTH-1:0]  r_axis_tdata;

logic                 sr_axis_tvalid;
logic   [DWIDTH-1:0]  sr_axis_tdata;

logic                 r_axis_ready;

logic                 load;
logic                 skid;

//------------------------------------------------------------------------------------------------//
// Control path
//------------------------------------------------------------------------------------------------//

always_ff @(posedge clk) begin
  if (rst) begin
    r_axis_tvalid  <= '0;
    r_axis_ready   <= '0;
    sr_axis_tvalid <= '0;
    skid           <= '0;
  end
  else begin
    if (skid && SKID) begin
      if (load) begin
        r_axis_tvalid <= sr_axis_tvalid;
        r_axis_ready  <= 1'b1;
        skid          <= 1'b0;
      end
    end
    else begin
      if (load) begin
        r_axis_tvalid <= i_axis_rx_tvalid;
        r_axis_ready  <= 1'b1;
        skid          <= 1'b0;
      end
      else begin
        sr_axis_tvalid <= i_axis_rx_tvalid;
        r_axis_ready   <= !i_axis_rx_tvalid;
        skid           <= i_axis_rx_tvalid;
      end
    end
  end
end

//------------------------------------------------------------------------------------------------//
// Data path (no reset needed)
//------------------------------------------------------------------------------------------------//
always_ff @(posedge clk) begin
  if (skid && SKID) begin
    if (load) begin
      r_axis_tdata  <= sr_axis_tdata;
    end
  end
  else begin
    if (load) begin
      r_axis_tdata  <= i_axis_rx_tdata;
    end
    else begin
      sr_axis_tdata  <= i_axis_rx_tdata;
    end
  end
end

// Load into register when data is valid and either reg is empty or reg is being sent
assign load  = (!r_axis_tvalid || i_axis_tx_tready);

assign o_axis_tx_tvalid = r_axis_tvalid;
assign o_axis_tx_tdata  = r_axis_tdata;
assign o_axis_rx_tready = (SKID) ? (r_axis_ready) : load;

endmodule
// SPDX-FileCopyrightText: Copyright (c) 2023-2024 NVIDIA CORPORATION & AFFILIATES. All rights reserved.
// SPDX-License-Identifier: Apache-2.0
//
// Licensed under the Apache License, Version 2.0 (the "License");
// you may not use this file except in compliance with the License.
// You may obtain a copy of the License at
//
// http://www.apache.org/licenses/LICENSE-2.0
//
// Unless required by applicable law or agreed to in writing, software
// distributed under the License is distributed on an "AS IS" BASIS,
// WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
// See the License for the specific language governing permissions and
// limitations under the License.

module axis_to_vec
#(
    parameter                               AXI_DWIDTH   = 64,
    parameter                               DATA_WIDTH   = 288,
    localparam                              W_KEEP       = (AXI_DWIDTH/8),
    localparam                              CNT_WIDTH    = $clog2(DATA_WIDTH/8)
)(
    input                                   clk,
    input                                   rst,
  //AXIS Interface
    input  logic                            i_axis_rx_tvalid,
    input  logic   [AXI_DWIDTH-1:0]         i_axis_rx_tdata,
    input  logic                            i_axis_rx_tlast,
    input  logic                            i_axis_rx_tuser,
    input  logic   [W_KEEP-1:0]             i_axis_rx_tkeep,
    output                                  o_axis_rx_tready,
    //Control
    input                                   i_done,
    output   [DATA_WIDTH-1:0]               o_data,
    output                                  o_valid,
    output                                  o_busy,
    output   [CNT_WIDTH-1:0]                o_byte_cnt
);

localparam D_CYCLES                     = (DATA_WIDTH-1)/AXI_DWIDTH + 1;

logic [CNT_WIDTH-1:0]         byte_cnt;
logic [ $clog2(D_CYCLES):0]   cnt;
logic                         pipe_incr;
logic                         early_pkt;
logic                         early_pkt_r;
logic [ $clog2(W_KEEP)-1:0]   byte_incr;
logic                         busy_r;

typedef enum logic [3:0] {
  A2V_IDLE = 4'b0001,
  A2V_DONE = 4'b0010,
  A2V_WAIT = 4'b0100,
  A2V_HOLD = 4'b1000
} a2v_states;
a2v_states a2v_state, a2v_state_nxt;

//------------------------------------------------------------------------------------------------//
// Buffer
//------------------------------------------------------------------------------------------------//

logic [AXI_DWIDTH-1:0]            data_buffer [D_CYCLES];
logic [(D_CYCLES*AXI_DWIDTH)-1:0] w_data;

genvar i;
generate
for (i=0;i<D_CYCLES;i=i+1) begin
  always_ff @(posedge clk) begin
    if (rst) begin
      data_buffer[i] <= '0;
    end
    else begin
      if (((a2v_state_nxt == A2V_IDLE) && (a2v_state != A2V_IDLE)) || (early_pkt_r && (i != 0))) begin // Reset pipe
        data_buffer[i] <= '0;
      end
      else if (pipe_incr) begin
        data_buffer[i] <= (cnt == i) ? i_axis_rx_tdata : data_buffer[i];
      end
    end
  end
end
endgenerate

assign pipe_incr = (i_axis_rx_tvalid && (a2v_state == A2V_IDLE));

//------------------------------------------------------------------------------------------------//
// FSM
//------------------------------------------------------------------------------------------------//

always_comb begin
  a2v_state_nxt = a2v_state;
  early_pkt     = '0;
  case(a2v_state)
    A2V_IDLE:   begin
      if (i_axis_rx_tvalid) begin
        early_pkt     = (i_axis_rx_tlast && (i_done));
        a2v_state_nxt = (i_axis_rx_tlast && (i_done))  ? A2V_IDLE:
                        (i_axis_rx_tlast && (!i_done)) ? A2V_HOLD:
                        (cnt == D_CYCLES-1)            ? A2V_WAIT:
                                                         A2V_IDLE;
      end
    end
    A2V_DONE: begin
      a2v_state_nxt = (i_axis_rx_tlast && i_axis_rx_tvalid) ? A2V_IDLE : A2V_DONE;
    end
    A2V_WAIT: begin
      a2v_state_nxt = (i_axis_rx_tlast && i_axis_rx_tvalid && i_done)  ? A2V_IDLE :
                      (i_axis_rx_tlast && i_axis_rx_tvalid && !i_done) ? A2V_HOLD :
                      (i_done)                                         ? A2V_DONE :
                                                                         A2V_WAIT ;
    end
    A2V_HOLD: begin
      a2v_state_nxt = (i_done) ? A2V_IDLE : A2V_HOLD;
    end
    default: begin
      a2v_state_nxt = A2V_IDLE;
    end
  endcase
end

always_ff @(posedge clk) begin
  if (rst) begin
    a2v_state   <= A2V_IDLE;
    byte_cnt    <= '0;
    cnt         <= '0;
    early_pkt_r <= '0;
    busy_r      <= '0;
  end
  else begin
    a2v_state   <= a2v_state_nxt;
    early_pkt_r <= early_pkt;
    busy_r      <= (a2v_state_nxt != A2V_IDLE);
    if (pipe_incr) begin
      cnt      <= (early_pkt) ? '0 : cnt + 1'b1;
      byte_cnt <= (early_pkt_r) ? byte_incr : byte_incr + byte_cnt;
    end
    else if (early_pkt_r) begin
      byte_cnt <= '0;
      cnt      <= '0;
    end
    else if ((a2v_state_nxt == A2V_IDLE) && (a2v_state != A2V_IDLE)) begin
      byte_cnt <= '0;
      cnt      <= '0;
    end
  end
end



//------------------------------------------------------------------------------------------------//
// Output
//------------------------------------------------------------------------------------------------//


genvar j;
generate
  if (DATA_WIDTH < AXI_DWIDTH) begin
    assign w_data = data_buffer[0][0+:DATA_WIDTH];
    assign byte_incr = $countones(i_axis_rx_tkeep[0+:(DATA_WIDTH/8)]);
  end
  else begin
    for (j=0; j<D_CYCLES; j=j+1) begin
      assign w_data[j*AXI_DWIDTH+:AXI_DWIDTH] = data_buffer[j];
    end
    assign byte_incr = $countones(i_axis_rx_tkeep);
  end
endgenerate

assign o_axis_rx_tready = (a2v_state_nxt == A2V_IDLE) || (a2v_state_nxt == A2V_DONE) || (a2v_state_nxt == A2V_WAIT);
assign o_valid = ((a2v_state == A2V_WAIT) || (a2v_state == A2V_HOLD) || (early_pkt_r));
assign o_busy = busy_r;
assign o_byte_cnt = byte_cnt;
assign o_data = w_data[DATA_WIDTH-1:0];

endmodule
