// CRC Calc
//------------------------------------------------------------------------------------------------//

logic              drp_valid;
logic              tlast_prev;
logic              fcs_tready;
logic              fcs_tvalid;

logic              drp_axis_tvalid;
logic              drp_axis_tlast;
logic [W_KEEP-1:0] drp_axis_tkeep;
logic [W_DATA-1:0] drp_axis_tdata;
logic              drp_axis_tuser;
logic              drp_axis_tready;
